import { GraphQLError } from 'graphql';
import { handleMaybePromise } from '@whatwg-node/promise-helpers';
import { isRequestBodyLimitError } from '../../error.js';
import { isContentTypeMatch } from './utils.js';
export function isPOSTJsonRequest(request) {
    return (request.method === 'POST' &&
        (isContentTypeMatch(request, 'application/json') ||
            isContentTypeMatch(request, 'application/graphql+json')));
}
export function parsePOSTJsonRequest(request) {
    return handleMaybePromise(() => request.json(), (requestBody) => {
        if (requestBody == null) {
            throw new GraphQLError(`POST body is expected to be object but received ${requestBody}`, {
                extensions: {
                    http: {
                        status: 400,
                    },
                    code: 'BAD_REQUEST',
                },
            });
        }
        const requestBodyTypeof = typeof requestBody;
        if (requestBodyTypeof !== 'object') {
            throw new GraphQLError(`POST body is expected to be object but received ${requestBodyTypeof}`, {
                extensions: {
                    http: {
                        status: 400,
                    },
                    code: 'BAD_REQUEST',
                },
            });
        }
        return requestBody;
    }, err => {
        if (err instanceof GraphQLError || isRequestBodyLimitError(err)) {
            throw err;
        }
        const extensions = {
            http: {
                spec: true,
                status: 400,
            },
            code: 'BAD_REQUEST',
        };
        if (err instanceof Error) {
            extensions['originalError'] = {
                name: err.name,
                message: err.message,
            };
        }
        throw new GraphQLError('POST body sent invalid JSON.', {
            extensions,
        });
    });
}
